CREATE TABLE remodel_durable_chunk (id INTEGER PRIMARY KEY, artifact_id INTEGER NOT NULL REFERENCES remodel_durable_artifact(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), field TEXT, element_type TEXT NOT NULL CHECK(element_type IN('raw','f32','u32','u8','text')), element_count INTEGER NOT NULL CHECK(element_count>=0), octets BLOB, UNIQUE(artifact_id,ordinal), CHECK((element_type='raw' AND field IS NULL AND octets IS NOT NULL AND element_count=length(octets)) OR (element_type!='raw' AND field IS NOT NULL AND octets IS NULL)));
CREATE TABLE remodel_durable_float (id INTEGER PRIMARY KEY, chunk_id INTEGER NOT NULL REFERENCES remodel_durable_chunk(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), sample REAL, sample_bits INTEGER NOT NULL CHECK(sample_bits BETWEEN 0 AND 4294967295), sample_class TEXT NOT NULL CHECK(sample_class IN('finite','nan','positiveInfinity','negativeInfinity')), UNIQUE(chunk_id,ordinal));
CREATE TABLE remodel_durable_integer (id INTEGER PRIMARY KEY, chunk_id INTEGER NOT NULL REFERENCES remodel_durable_chunk(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 4294967295), UNIQUE(chunk_id,ordinal));
CREATE TABLE remodel_durable_byte (id INTEGER PRIMARY KEY, chunk_id INTEGER NOT NULL REFERENCES remodel_durable_chunk(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 255), UNIQUE(chunk_id,ordinal));
CREATE TABLE remodel_durable_text (id INTEGER PRIMARY KEY, chunk_id INTEGER NOT NULL UNIQUE REFERENCES remodel_durable_chunk(id), content TEXT NOT NULL);
